/**
 * 改造自 shadcn 原装 base-lyra tooltip（https://ui.shadcn.com/r/styles/base-lyra/tooltip.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。`Tooltip` 收 `motion`，经 context 交给 `TooltipContent`，
 *    弹层渲染 `data-motion`。删掉弹层上的 tw-animate-css 类（`data-open:animate-in`、`fade-*`、`zoom-*`、
 *    `slide-in-from-*`，以及 Radix 遗留的 `data-[state=delayed-open]:*`）与 `origin-(--transform-origin)`：
 *    预设自己读 Base UI 的 `--transform-origin`。
 * 2. 加 `data-instant:transition-none`：在一组提示之间移动、由焦点打开或被直接关掉时，Base UI 给弹层加
 *    `data-instant`，这时不过渡（Base UI 文档的写法）。
 * 此外只有格式化与一条 Biome 豁免注释，其余类名逐字保留。
 */
"use client";

import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "cn";
import { createContext, use } from "react";

/**
 * 提示支持的动效预设（ADR 0021）。缺省 `fade`：提示要快，不缩放。
 * - `fade`：只淡入淡出，150ms。
 * - `pop`：从触发器一侧淡入加缩放 96%→100%，200ms。
 */
type TooltipMotion = "fade" | "pop";

const TooltipMotionContext = createContext<TooltipMotion>("fade");

function TooltipProvider({ delay = 0, ...props }: TooltipPrimitive.Provider.Props) {
  return <TooltipPrimitive.Provider data-slot="tooltip-provider" delay={delay} {...props} />;
}

function Tooltip({
  motion = "fade",
  ...props
}: TooltipPrimitive.Root.Props & { motion?: TooltipMotion }) {
  return (
    <TooltipMotionContext value={motion}>
      <TooltipPrimitive.Root data-slot="tooltip" {...props} />
    </TooltipMotionContext>
  );
}

function TooltipTrigger({ ...props }: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContent({
  className,
  side = "top",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  children,
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">) {
  const motion = use(TooltipMotionContext);
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        className="isolate z-50"
      >
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          data-motion={motion}
          className={cn(
            "z-50 inline-flex w-fit max-w-xs items-center gap-1.5 rounded-none bg-foreground px-3 py-1.5 text-xs text-background has-data-[slot=kbd]:pr-1.5 data-instant:transition-none **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-none",
            className,
          )}
          {...props}
        >
          {children}
          <TooltipPrimitive.Arrow
            // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的箭头位置（半个箭头加 2px 间距）。
            className="z-50 size-2.5 translate-y-[calc(-50%-2px)] rotate-45 rounded-none bg-foreground fill-foreground data-[side=bottom]:top-1 data-[side=inline-end]:top-1/2! data-[side=inline-end]:-left-1 data-[side=inline-end]:-translate-y-1/2 data-[side=inline-start]:top-1/2! data-[side=inline-start]:-right-1 data-[side=inline-start]:-translate-y-1/2 data-[side=left]:top-1/2! data-[side=left]:-right-1 data-[side=left]:-translate-y-1/2 data-[side=right]:top-1/2! data-[side=right]:-left-1 data-[side=right]:-translate-y-1/2 data-[side=top]:-bottom-2.5"
          />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, type TooltipMotion, TooltipProvider, TooltipTrigger };
